use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let cents = input.as_i64().unwrap();
    let n = cents as usize;
    let mut shares = Vec::new();

    for i in 0..=n {
        let share = cents / n;
        shares.push(share);
        cents -= share;
    }

    shares.sort_unstable();
    shares.reverse();
    shares.into_iter().map(|&x| serde_json::Value::from(x)).collect()
}

fn main() {
    let input = serde_json::Value::from("{\"input\":[10,3]}");
    let expected = serde_json::Value::from(vec![4, 3, 3]});
    assert_eq!(solve(input), expected);
}
